var EXTRA=[{"dot": "gray", "j": "Arthroscopy", "h": "Editoriale: nel ginocchio senza crociato i menischi posteriori vanno guardati come stabilizzatori secondari", "v": "Commento di opinione, senza dati nuovi: richiama studi su cadavere secondo cui rampa mediale e radice laterale aumentano la lassità, ma l'instabilità biomeccanica non si traduce per forza in esiti peggiori riferiti dal paziente.", "pmid": "42989692", "doi": "10.1002/arj.70769", "temi": ["menisco", "LCA", "lesione a rampa"]}, {"dot": "gray", "j": "Front Surg", "h": "Impronta femorale del LCA: forma variabile in cadavere, e un tunnel rotondo ne copre meno di metà", "v": "Studio su ginocchia di cadavere, pochi esemplari: propone tunnel ellittici e innesti rettangolari per le impronte ovali ampie, ma senza esiti clinici; gli autori chiedono validazione su casistiche più grandi.", "pmid": "42984648", "doi": "10.3389/fsurg.2026.1897000", "temi": ["LCA", "impronta femorale", "tunnel"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Ancore rotulee per il MPFL: in laboratorio le rigide senza nodi tengono meglio, e la sede superomediale pure", "v": "Modello su cadavere con poche ancore per tipo: misura la fissazione, non gli esiti nei pazienti; la sede superomediale tiene di più anche perché l'osso è più denso.", "pmid": "42989714", "doi": "10.1002/arj.70681", "temi": ["MPFL", "ancore", "biomeccanica"]}, {"dot": "gray", "j": "Health Expect", "h": "Lesione degenerativa del menisco: sviluppato un intervento per medici di base e pazienti, per portare l'esercizio prima dell'artroscopia", "v": "Descrive come è stato costruito, con interviste e consultazioni, un intervento educativo; non ha ancora dati di efficacia. Le linee guida internazionali raccomandano educazione ed esercizio come prima scelta.", "pmid": "42993636", "doi": "10.1111/hex.70940", "temi": ["menisco degenerativo", "artrosi precoce", "implementazione"]}, {"dot": "gray", "j": "Clin Physiol Funct Imaging", "h": "Grasso intramuscolare del vasto mediale: si associa alla progressione del danno di qualità della cartilagine femorale mediale a tre anni", "v": "Coorte prospettica di anziani, con parte dei partecipanti persa al follow-up: associazione di imaging (T2 della cartilagine), senza esiti clinici e senza dimostrare che allenare il muscolo cambi la cartilagine.", "pmid": "42989944", "doi": "10.1111/cpf.70107", "temi": ["quadricipite", "cartilagine", "risonanza T2"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Nefopam endovena prima dell'incisione nella protesi totale: meno dolore dinamico e meno morfina in un RCT piccolo", "v": "RCT in triplo cieco a centro unico con campione piccolo; più tachicardia nel braccio trattato. Valuta analgesia e dimissione e non la protesi; resta da confermare su più centri.", "pmid": "42994642", "doi": "10.1016/j.arth.2026.11.009", "temi": ["protesi totale", "analgesia", "RCT"]}, {"dot": "gray", "j": "Blood Coagul Fibrinolysis", "h": "Acido tranexamico endovena e intra-articolare ad alta quota: nessun tromboembolismo in uno studio pilota, ma con pochi pazienti", "v": "RCT pilota a centro unico ad altitudine elevata: nessun evento in nessun braccio, quindi lo studio non può escludere un rischio e non va letto come prova di sicurezza.", "pmid": "42989838", "doi": "10.1097/MBC.0000000000001472", "temi": ["protesi totale", "acido tranexamico", "tromboembolismo"]}, {"dot": "gray", "j": "Arthroplasty", "h": "Monocompartimentale mediale: il cambio di fenotipo CPAK dopo l'impianto non peggiora i punteggi a circa due anni", "v": "Coorte in cui una parte dei pazienti non ha avuto radiografie adatte e i due gruppi sono piccoli: dice che i punteggi a breve termine non differiscono, non che il fenotipo sia indifferente a lungo termine.", "pmid": "42978021", "doi": "10.1186/s42836-026-00447-x", "temi": ["monocompartimentale", "CPAK", "allineamento"]}, {"dot": "gray", "j": "J Orthop Sci", "h": "Protesi di ginocchio bilaterale nella stessa seduta: più trombosi venosa profonda ed embolia polmonare in un grande database giapponese", "v": "Coorte retrospettiva da dati amministrativi con appaiamento per propensity score: associazioni, non cause; la sicurezza della seduta unica dipende dalla selezione dei pazienti.", "pmid": "42982668", "doi": "10.1016/j.jos.2026.10.012", "temi": ["protesi bilaterale", "tromboembolismo", "database"]}, {"dot": "gray", "j": "Front Bioeng Biotechnol", "h": "Staminali nella guarigione tendine-osso dopo LCA: nei modelli animali migliorano carico a rottura e integrazione, con eterogeneità alta", "v": "Meta-analisi di studi controllati su animali, rischio di bias moderato: non dice nulla sull'uomo e richiede protocolli preclinici standardizzati prima di qualunque traslazione.", "pmid": "42978926", "doi": "10.3389/fbioe.2026.1869863", "temi": ["LCA", "tendine-osso", "cellule staminali"]}];

var SCOPERTE=[{"t": "Osteocondrite dissecante giovanile: i chirurghi dell'Asia-Pacifico e quelli europei non la trattano allo stesso modo", "v": "Un sondaggio fra chirurghi della rete pediatrica Asia-Pacifico, confrontato con quello ESSKA del 2023: i primi usano più TC, artroscopia per la stabilità, immobilizzazione e trapianto osteocondrale, i secondi più risonanza e microfratture. Una finestra su una pratica che hai dichiarato di conoscere poco; sono preferenze dichiarate, non un confronto di esiti.", "pmid": "42985630", "doi": "10.1002/ars2.70154", "temi": ["osteocondrite dissecante", "Asia-Pacifico", "variabilità della pratica"]}, {"t": "Lesione parziale del crociato curata senza intervento: il caso di un giocatore di hockey su prato tornato alla finale olimpica", "v": "Caso singolo di lesione femorale con fibre in continuità (Sherman II), trattamento non operatorio e riabilitazione a criteri oggettivi; argento olimpico circa duecento giorni dopo. È un aneddoto e non una prova, ma ricorda che la morfologia della lesione può contare nell'indicazione.", "pmid": "42992267", "doi": "10.26603/001c.172792", "temi": ["LCA", "trattamento non operatorio", "caso clinico"]}, {"t": "Un legamento artificiale di cellulosa batterica con architettura a spirale: la bioingegneria cinese per la ricostruzione del LCA", "v": "Studio di ingegneria dei tessuti (Science Bulletin): resistenza paragonabile ai legamenti sintetici in PET e minore allargamento del tunnel negli esperimenti in vivo. Nessun dato umano; mostra in che direzione si muove la ricerca sugli innesti.", "pmid": "42977630", "doi": "10.1016/j.scib.2026.10.056", "temi": ["bioingegneria", "LCA", "legamento artificiale"]}];

var SOC={"1": {"video": "Dopo la ricostruzione del legamento crociato anteriore si misura la forza dei muscoli della coscia. Uno studio svedese su 3.458 persone operate con i tendini della parte posteriore della coscia ha guardato un rapporto: la forza dei muscoli posteriori rispetto a quella del quadricipite, misurata a sei mesi.\n\nChi aveva un rapporto più alto aveva meno probabilità di essere rioperato entro due anni (odds ratio 0,81, intervallo di confidenza 0,71-0,93). Ma il test non è abbastanza preciso da dire quale singolo paziente sarà rioperato, e un rapporto più alto si associava a un salto su una gamba più asimmetrico.\n\nIl limite: i dati vengono da un solo centro e da un solo tipo di tendine; non dicono nulla sul quadricipite usato come innesto. È un dato in più, non una soglia per tornare allo sport.\nFonte: PubMed, PMID 42994101.", "linkedin": "Rapporto forza ischiocrurali/quadricipite a 6 mesi dopo LCA e revisione entro 2 anni: analisi di un registro di Stoccolma (KSSTA, 2026), 3.458 operati con innesto di ischiocrurali.\n\nPer ogni aumento di 10 unità del rapporto misto eccentrico/concentrico, OR di revisione 0,81 (IC 95% 0,71-0,93; p = 0,003). Capacità discriminante scarsa: AUC 0,64. Rapporto più alto associato a LSI del salto monopodalico peggiore (β −1,30; IC 95% da −1,51 a −1,09).\n\nIl limite: livello III, un solo centro, solo ischiocrurali, numero di revisioni non riportato. Non indica una soglia di rientro.\nFonte: PubMed, PMID 42994101.", "instagram": "Crociato operato: forza della coscia a 6 mesi e rischio di nuova operazione.\n\nRapporto più alto, meno nuove operazioni (OR 0,81; IC 95% 0,71-0,93), ma il test non è preciso (AUC 0,64).\n\nUn solo centro, un solo tipo di innesto. PMID 42994101.", "pazienti": "Legamento crociato operato: cosa dice la forza dei muscoli della coscia a sei mesi? Uno studio svedese su 3.458 persone.\n\nChi aveva i muscoli dietro la coscia relativamente più forti è stato rioperato meno spesso entro due anni, ma la misura non basta a prevedere cosa accadrà a una singola persona.\n\nIl limite: un solo centro, un solo tipo di tendine. Per il proprio caso conta il parere del chirurgo e del fisioterapista.\nFonte: PubMed, PMID 42994101."}};

var SOCV={"1": {"video": {"chir": ["Rapporto ischiocrurali-quadricipite a sei mesi dopo ricostruzione del LCA e revisione entro due anni (KSSTA, 2026). Registro di Stoccolma, 3.458 operati con innesto di ischiocrurali, forza isocinetica al Biodex a sei mesi: ischiocrurali in eccentrica, quadricipite in concentrica, rapporto misto.", "Per ogni aumento di 10 unità del rapporto, la probabilità di revisione entro due anni scende: OR aggiustato 0,81, IC 95% 0,71-0,93. Ma l'area sotto la curva è 0,64, quindi il test discrimina male e non identifica chi sarà rioperato. Un rapporto più alto si associa anche a un salto monopodalico più asimmetrico: beta meno 1,30, IC 95% da meno 1,51 a meno 1,09.", "Il limite: livello III, registro di un solo centro, solo innesto di ischiocrurali, numero di revisioni e unità del rapporto non riportati nell'abstract. Nulla sul quadricipite: non indica una soglia di rientro.\nFonte: PubMed, PMID 42994101."], "misto": ["Dopo la ricostruzione del legamento crociato anteriore si misura la forza dei muscoli della coscia. Uno studio svedese su 3.458 persone operate con i tendini della parte posteriore della coscia ha guardato un rapporto: la forza dei muscoli posteriori rispetto a quella del quadricipite, misurata a sei mesi.", "Chi aveva un rapporto più alto aveva meno probabilità di essere rioperato entro due anni (odds ratio 0,81, intervallo di confidenza 0,71-0,93). Ma il test non è abbastanza preciso da dire quale singolo paziente sarà rioperato, e un rapporto più alto si associava a un salto su una gamba più asimmetrico.", "Il limite: i dati vengono da un solo centro e da un solo tipo di tendine; non dicono nulla sul quadricipite usato come innesto. È un dato in più, non una soglia per tornare allo sport.\nFonte: PubMed, PMID 42994101."], "pazienti": ["Dopo un'operazione al legamento crociato del ginocchio, i medici misurano la forza dei muscoli della coscia. Uno studio svedese su 3.458 persone ha confrontato, a sei mesi dall'operazione, la forza dei muscoli dietro la coscia con quella davanti.", "Chi aveva i muscoli dietro la coscia relativamente più forti è stato rioperato meno spesso nei due anni successivi. Però la misura non basta a prevedere cosa succederà a una singola persona e non sostituisce gli altri controlli che si fanno prima di tornare allo sport.", "Il limite: lo studio viene da un solo centro e riguarda un solo tipo di tendine usato per il legamento. Per il proprio caso serve il parere del proprio chirurgo e del fisioterapista.\nFonte: PubMed, PMID 42994101."]}, "linkedin": {"chir": ["Rapporto forza ischiocrurali/quadricipite a 6 mesi dopo LCA e revisione entro 2 anni: analisi di un registro di Stoccolma (KSSTA, 2026), 3.458 operati con innesto di ischiocrurali.", "Per ogni aumento di 10 unità del rapporto misto eccentrico/concentrico, OR di revisione 0,81 (IC 95% 0,71-0,93; p = 0,003). Capacità discriminante scarsa: AUC 0,64. Rapporto più alto associato a LSI del salto monopodalico peggiore (β −1,30; IC 95% da −1,51 a −1,09).", "Il limite: livello III, un solo centro, solo ischiocrurali, numero di revisioni non riportato. Non indica una soglia di rientro.\nFonte: PubMed, PMID 42994101."], "misto": ["Forza dei muscoli della coscia sei mesi dopo la ricostruzione del crociato anteriore e rischio di nuova operazione: uno studio svedese su 3.458 persone (KSSTA, 2026).", "Un rapporto più alto fra la forza dei muscoli posteriori della coscia e quella del quadricipite si associa a meno revisioni entro due anni (OR 0,81; IC 95% 0,71-0,93), ma il test non individua con precisione chi sarà rioperato (AUC 0,64).", "Il limite: un solo centro, solo innesto con tendini posteriori della coscia, numero di rioperazioni non riportato; non è una soglia di rientro.\nFonte: PubMed, PMID 42994101."], "pazienti": ["Legamento crociato operato: cosa dice la forza dei muscoli della coscia a sei mesi? Uno studio svedese su 3.458 persone.", "Chi aveva i muscoli dietro la coscia relativamente più forti è stato rioperato meno spesso entro due anni, ma la misura non basta a prevedere cosa accadrà a una singola persona.", "Il limite: un solo centro, un solo tipo di tendine. Per il proprio caso conta il parere del chirurgo e del fisioterapista.\nFonte: PubMed, PMID 42994101."]}, "instagram": {"chir": ["Forza a 6 mesi dopo LCA: il rapporto ischiocrurali/quadricipite e le revisioni.", "Rapporto più alto, meno revisioni (OR 0,81; IC 95% 0,71-0,93), ma test poco discriminante (AUC 0,64).", "Registro di un centro, solo ischiocrurali. PMID 42994101."], "misto": ["Crociato operato: forza della coscia a 6 mesi e rischio di nuova operazione.", "Rapporto più alto, meno nuove operazioni (OR 0,81; IC 95% 0,71-0,93), ma il test non è preciso (AUC 0,64).", "Un solo centro, un solo tipo di innesto. PMID 42994101."], "pazienti": ["Crociato operato: la forza della coscia a 6 mesi dice qualcosa sul rischio di nuova operazione.", "Muscoli dietro la coscia relativamente più forti, meno nuove operazioni; ma non vale per ogni singola persona.", "Un solo centro, un solo tipo di tendine. PMID 42994101."]}, "reel": {"chir": ["[Forza e revisione del LCA]", "Rapporto più alto a 6 mesi, meno revisioni; AUC 0,64.", "Registro monocentrico. PMID 42994101."], "misto": ["[Crociato e forza]", "Rapporto più alto, meno nuove operazioni; test poco preciso.", "Un centro, un tipo di innesto. PMID 42994101."], "pazienti": ["[Crociato e muscoli]", "Più forza dietro la coscia, meno nuove operazioni, in media.", "Non prevede il singolo caso. PMID 42994101."]}}};

var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #riabilitazione #medicinadellosport #chirurgiadelginocchio #medicinabasatasulleprove #ortopediaticino #ticino", "kw": "legamento crociato anteriore, ricostruzione del crociato, forza muscolare dopo il crociato, riabilitazione del crociato, ginocchio operato, ritorno allo sport"}};

var NLB={"1": {"prof": ["Rapporto ischiocrurali/quadricipite a 6 mesi dopo LCA e revisione entro 2 anni: analisi di registro", "Analisi di registro monocentrico (KSSTA, 2026; livello III, solo abstract): 3.458 operati di LCA con innesto di ischiocrurali. Ogni aumento di 10 unità del rapporto misto eccentrico/concentrico a 6 mesi si associa a una minore probabilità di revisione entro 2 anni (OR 0,81; IC 95% 0,71-0,93) e a un LSI del salto monopodalico peggiore (β −1,30; IC 95% da −1,51 a −1,09).", "Nota critica: AUC 0,64, quindi capacità discriminante scarsa; solo ischiocrurali; numero di revisioni e unità del rapporto non riportati; nessuna soglia di rientro."], "mix": ["Dopo il crociato: la forza della coscia a sei mesi e il rischio di una nuova operazione", "Uno studio svedese su 3.458 persone operate di legamento crociato con i tendini della parte posteriore della coscia ha confrontato, a sei mesi, la forza dei muscoli posteriori con quella del quadricipite. Un rapporto più alto si associava a meno nuove operazioni entro due anni, ma anche a un salto su una gamba più asimmetrico.", "Nota sul limite: il test non è abbastanza preciso da prevedere il singolo caso e riguarda un solo tipo di innesto e un solo centro; non indica quando tornare allo sport."], "paz": ["Crociato operato: cosa dice la forza della coscia a sei mesi", "In uno studio svedese su 3.458 persone, chi dopo sei mesi aveva i muscoli dietro la coscia relativamente più forti è stato rioperato meno spesso nei due anni successivi. La misura è un'informazione in più per il fisioterapista e il chirurgo, non una regola per il singolo.", "Nota rassicurante: nessuna misura da sola decide il ritorno allo sport; il percorso si definisce con il proprio chirurgo e fisioterapista."], "kw": "legamento crociato, ricostruzione del crociato, forza muscolare, riabilitazione, ginocchio operato"}, "2": {"prof": ["Innesti per LCA: quadricipite e rotuleo di maggior valore in un modello economico a 5 anni", "Analisi decisionale di Markov (Arthroscopy, 2026; livello III, solo abstract). Costo a 5 anni 3.917 dollari per il rotuleo e 4.901 per il quadricipite; QALY 4,589 e 4,612. ICER del quadricipite sul rotuleo 42.905 dollari per QALY (soglia 50.000). Ischiocrurali e allotrapianto costano di più e rendono meno.", "Nota critica: il quadricipite è preferito nel 55,7% delle simulazioni e il rotuleo nel 44,3%; piccole variazioni di costo o di morbilità invertono la scelta; è un modello, non esiti clinici."], "mix": ["Quale tendine per il crociato: un modello economico confronta costi ed efficacia", "Un'analisi che simula cinque anni di costi e qualità di vita dopo la ricostruzione del crociato indica che i tendini del quadricipite e della rotula offrono il maggior valore, mentre quelli posteriori della coscia e il tendine da donatore costano di più e rendono meno. La differenza fra i primi due è piccola.", "Nota sul limite: è una simulazione con dati tratti dalla letteratura e non uno studio sui pazienti; con piccole variazioni dei dati in ingresso la scelta fra i due si inverte."], "paz": ["Ricostruzione del crociato: la scelta del tendine non dipende solo dal costo", "Un'analisi economica ha confrontato quattro tipi di tendine per ricostruire il crociato. Due risultano di maggior valore nel modello, ma le differenze sono piccole e gli autori scrivono che la scelta va fatta caso per caso con il chirurgo.", "Nota rassicurante: i risultati dipendono dalle ipotesi del modello e non dicono quale tendine sia adatto a una singola persona."], "kw": "legamento crociato, innesto del crociato, costo-efficacia, tendine del quadricipite"}, "3": {"prof": ["LCA in giocatori di futsal: lesioni condrali più frequenti nelle revisioni, per lo più di grado basso", "Serie retrospettiva consecutiva (KSSTA, 2026; livello IV, solo abstract): 331 giocatori. Lesioni associate nel 57,1% (meniscali 51,4%, condrali 20,5%). Nelle revisioni lesioni condrali 55,9% contro 16,2%; OR aggiustato 6,36 (IC 95% 2,94-13,74).", "Nota critica: circa 34 revisioni; con soglia Outerbridge ≥ 2 l'OR è 2,13 (IC 95% 0,87-5,23), non significativo; disegno trasversale, un solo centro."], "mix": ["Crociato rioperato: più danni alla cartilagine nei giocatori di futsal", "In 331 giocatori di futsal operati di legamento crociato, più della metà aveva anche una lesione del menisco o della cartilagine. Chi veniva rioperato aveva molto più spesso un danno alla cartilagine, quasi sempre di grado lieve.", "Nota sul limite: i casi di nuova operazione sono pochi e il risultato diventa incerto se si considerano solo i danni più importanti; lo studio non dice se questi danni cambino l'esito."], "paz": ["Crociato e cartilagine: cosa si trova durante una seconda operazione", "In uno studio su 331 giocatori di futsal, durante la ricostruzione del crociato si trovavano spesso anche lesioni del menisco o della cartilagine. Nelle seconde operazioni il danno alla cartilagine era più frequente, per lo più lieve.", "Nota rassicurante: i danni lievi sono comuni e lo studio non dimostra che peggiorino il risultato; la valutazione spetta al proprio chirurgo."], "kw": "legamento crociato, futsal, cartilagine, menisco, seconda operazione"}, "4": {"prof": ["Instabilità rotulea: MPFL e trocleoplastica riducono la rotazione tibio-femorale, legata al PT-TGA", "Serie retrospettiva (JEO, 2026; livello IV, solo abstract): 141 pazienti, MPFL più trocleoplastica a lembo sottile, osteotomia della tuberosità se indicata. TFR −1,55° (IC 95% 0,86-2,23; p < 0,001); PT-TGA −10,02°; il PT-TGA è l'unico predittore indipendente della TFR preoperatoria e della sua variazione.", "Nota critica: nessun esito clinico nell'abstract e nessun confronto; gli effetti di MPFL, trocleoplastica e osteotomia non sono separabili."], "mix": ["Rotula instabile: dopo l'intervento il ginocchio ruota un po' meno", "In 141 persone operate per una rotula che tende a uscire dalla sede, l'allineamento della rotula migliorava dopo l'intervento e anche la rotazione del ginocchio si riduceva di circa un grado e mezzo. La rotazione sembra dipendere dall'allineamento dell'apparato che estende il ginocchio.", "Nota sul limite: lo studio misura immagini e non il risultato clinico, e non c'è un gruppo di confronto."], "paz": ["Rotula instabile: cosa cambia nelle immagini dopo l'operazione", "In uno studio su 141 persone operate per instabilità della rotula, le misure dell'allineamento miglioravano dopo l'intervento e il ginocchio ruotava leggermente meno.", "Nota rassicurante: sono misure sulle immagini e non il risultato per il paziente; l'esito si valuta insieme al proprio chirurgo."], "kw": "instabilità della rotula, legamento patello-femorale mediale, trocleoplastica, ginocchio"}, "5": {"prof": ["Protesi robotica: precisione documentata, beneficio clinico incoerente; revisione narrativa", "Revisione narrativa di esperti (J Robot Surg, 2026; solo abstract). Meno errori di allineamento e di posizionamento dei componenti; benefici funzionali e perioperatori variabili per procedura, piattaforma e follow-up. Gli autori propongono la «distanza fra precisione e bersaglio».", "Nota critica: nessun dato aggregato nell'abstract; tre autori affiliati a un produttore di sistemi robotici; piattaforme non distinte."], "mix": ["Protesi robotica: tagli precisi, ma il vantaggio clinico non è dimostrato in modo uniforme", "Una revisione di esperti conferma che il robot riduce gli errori di posizionamento della protesi, mentre i benefici su funzione e recupero variano da caso a caso e nel tempo. Secondo gli autori, una precisione maggiore serve poco se l'obiettivo chirurgico non è provato per quel paziente.", "Nota sul limite: è una revisione narrativa, senza numeri nell'abstract, e tre autori sono affiliati a un'azienda del settore."], "paz": ["Protesi con il robot: cosa è provato e cosa no", "Una revisione di esperti riassume che l'uso del robot rende più precisa la posizione della protesi. Non è invece chiaro, in modo valido per tutti, che questo porti un recupero migliore a lungo termine.", "Nota rassicurante: la tecnica scelta dal chirurgo resta una decisione da discutere caso per caso."], "kw": "protesi di ginocchio robotica, protesi totale di ginocchio, allineamento, chirurgia robotica"}};

var ARTICLES=[{n:1,mono:'m-gray',dot:'green',sec:'res',j:'KSSTA',h:'Rapporto ischiocrurali/quadricipite a 6 mesi dopo LCA: più alto, meno revisioni a 2 anni, ma il test discrimina male',v:'Analisi di un registro locale (Capio Artro Clinic, Stoccolma; livello III): 3.458 operati di LCA con innesto di ischiocrurali. Per ogni aumento di 10 unità del rapporto misto fra forza eccentrica degli ischiocrurali e concentrica del quadricipite a 6 mesi, la probabilità di revisione entro 2 anni scende (OR aggiustato 0,81; IC 95% 0,71-0,93), ma la capacità discriminante è scarsa (AUC 0,64). Un rapporto più alto si associa anche a un salto monopodalico più asimmetrico.',ax:'Högberg, Cristiani, Samuelsson, Mikkelsen, Hamrin Senorski',date:'nov 2026',meta:'analisi di registro locale, 3.458 operati con ischiocrurali, livello III, solo abstract',pmid:'42994101',doi:'10.1002/ksa.70679',journal:'Knee surgery, sports traumatology, arthroscopy',authors:'Högberg J, Cristiani R, Samuelsson K, Mikkelsen C, Hamrin Senorski E',design:'Dati da un registro locale della Capio Artro Clinic (Stoccolma): pazienti dai 15 anni in su operati di LCA primario con innesto di ischiocrurali fra il 2005 e il 2021, senza lesioni legamentose associate né resezione o sutura meniscale. A 6 mesi forza isocinetica al dinamometro Biodex, ischiocrurali in eccentrica e quadricipite in concentrica; regressione logistica multivariata aggiustata per età e livello Tegner pre-infortunio, regressione lineare per il salto. Livello III. Non è indicato nell\'abstract se la raccolta fosse prospettica; numero di revisioni, unità della scala del rapporto e dati mancanti: non riportati.',pop:'3.458 operati (49,5% donne; età media 28,8 ± 10,4 anni), tutti con innesto di ischiocrurali e senza lesioni legamentose o meniscali trattate in associazione. Nessun innesto di quadricipite o di retto femorale: la popolazione non coincide con quella del tuo innesto.',results:'A 6 mesi chi è andato incontro a revisione entro 2 anni aveva un rapporto misto più basso sull\'arto operato. Aggiustato per età e Tegner pre-infortunio, ogni aumento di 10 unità riduce la probabilità di revisione (OR 0,81; IC 95% 0,71-0,93; p = 0,003), ma l\'AUC è 0,64, cioè la capacità discriminante è scarsa. Un rapporto più alto si associa a un LSI del salto monopodalico peggiore (β −1,30; IC 95% da −1,51 a −1,09; p < 0,001). Numero di revisioni e unità del rapporto: non riportati nell\'abstract.',concl:'Gli autori: il rapporto misto può integrare la valutazione del recupero muscolare dopo LCA, ma la scarsa capacità discriminante ne limita l\'uso per identificare chi andrà incontro a revisione.',limits:'Analisi di registro monocentrico, livello III: associazione, non causa · Solo innesto di ischiocrurali · AUC 0,64, poco sopra il caso (0,5): non è uno strumento per decidere il rientro del singolo paziente · Numero di revisioni, unità del rapporto e dati mancanti non sono nell\'abstract · Un rapporto alto può riflettere anche un quadricipite relativamente più debole e non solo ischiocrurali più forti (mia lettura, non dell\'abstract) · È un test di forza: non misura prontezza psicologica né qualità del movimento',perte:'Verde: tocca la tensione sul criterio di rientro (T4 dell\'app). Il tuo innesto è il quadricipite o il retto femorale, non gli ischiocrurali, quindi il dato non è trasferibile: lo studio non dice che un rapporto alto protegga dalla revisione sul tuo innesto e non fissa alcuna soglia. Nello stesso studio un rapporto più alto si associa a un salto più asimmetrico: è un argomento in più per non affidare il rientro a un solo numero al dinamometro. Cosa fare: nessun cambio; se usi l\'isocinetico, non adottare il rapporto come soglia di rientro senza un dato sul tuo innesto.'},
{n:2,mono:'m-gray',dot:'green',sec:'res',j:'Arthroscopy',h:'Crociato: quadricipite e rotuleo hanno il maggior valore in un modello a 5 anni, ma la differenza fra i due è instabile',v:'Analisi decisionale di Markov (Mayo Clinic; livello III) su costi a 5 anni e anni di vita aggiustati per qualità (QALY), con probabilità tratte dalla letteratura e costi da dati multicentrici. Rotuleo e quadricipite hanno il maggior valore; ischiocrurali e allotrapianto costano di più e rendono meno. Il quadricipite supera il rotuleo con un ICER di 42.905 dollari per QALY (soglia 50.000), ma è preferito solo nel 55,7% delle simulazioni.',ax:'Dean, Hevesi, Tagliero, Duchman, Krych',date:'nov 2026',meta:'analisi decisionale di Markov, livello III, solo abstract',pmid:'42989730',doi:'10.1002/arj.70713',journal:'Arthroscopy',authors:'Dean MC, Hevesi M, Tagliero AJ, Duchman KR, Krych AJ',design:'Modello di Markov a 5 anni che confronta rotuleo (BPTB), ischiocrurali, quadricipite e allotrapianto per la ricostruzione del LCA. Le probabilità di rottura dell\'innesto, morbilità del sito donatore, infezione e revisione derivano dalla letteratura recente; i costi diretti da dati multicentrici con costing per attività guidato dal tempo. Analisi di sensibilità deterministiche e probabilistiche. Livello III, analisi economica e decisionale. Valuta in dollari; sistema sanitario di riferimento, costi di ischiocrurali e allotrapianto, intervalli dei QALY e fonti delle probabilità: non riportati nell\'abstract.',pop:'Non applicabile (modello): coorte ipotetica di operati di LCA primario, nessun paziente arruolato.',results:'Costo a 5 anni 3.917 dollari per il rotuleo contro 4.901 per il quadricipite; QALY 4,589 contro 4,612. Il quadricipite è costo-efficace rispetto al rotuleo con un ICER di 42.905 dollari per QALY alla soglia di 50.000. Ischiocrurali e allotrapianto sono più costosi e meno efficaci nel caso base. Piccole variazioni invertono la scelta (costo del rotuleo −4,5% o del quadricipite +3,7%; morbilità del donatore del rotuleo da 43,0% a 39,9% o del quadricipite da 2,9% a 7,8%). Nelle simulazioni probabilistiche il quadricipite è preferito nel 55,7% dei casi, il rotuleo nel 44,3%, e il quadricipite domina nel 22,4%. Intervalli di confidenza dei QALY: non riportati nell\'abstract.',concl:'Gli autori: quadricipite e rotuleo offrono il maggior valore, il quadricipite con efficacia modellata appena maggiore e il rotuleo con il costo minore; ischiocrurali e allotrapianto costano di più e rendono meno. Data la sensibilità a fattori del chirurgo, ai costi operatori e alla morbilità del donatore, la scelta dell\'innesto deve restare individuale e non guidata dal solo costo.',limits:'È un modello e non uno studio sui pazienti: gli esiti dipendono dalle stime tratte dalla letteratura · Livello III · La differenza di efficacia fra quadricipite e rotuleo è di 0,023 QALY in 5 anni (calcolo mio) e la scelta si inverte con variazioni modeste dei dati in ingresso · Valuta in dollari e sistema sanitario non dichiarati: costi non trasferibili ai tariffari svizzeri · L\'abstract non specifica se il quadricipite sia con o senza blocco osseo e non modella il retto femorale · Intervalli dei QALY e costi di ischiocrurali e allotrapianto non riportati',perte:'Verde: il quadricipite, che usi, risulta fra le due scelte di maggior valore, ma il modello non lo separa in modo stabile dal rotuleo (preferito nel 55,7% delle simulazioni) e non modella il retto femorale. È un argomento di costo-efficacia e non di esito clinico: non cambia la tua scelta dell\'innesto. Cosa fare: nessun cambio; se confronti gli innesti con un paziente o un assicuratore, presenta il dato come modello con costi in dollari e non come prova che il quadricipite sia superiore.'},
{n:3,mono:'m-gray',dot:'green',sec:'res',j:'KSSTA',h:'LCA in calciatori di futsal: nelle revisioni le lesioni condrali sono molto più frequenti, ma per lo più di grado basso',v:'Serie retrospettiva consecutiva (Instituto Cugat, Barcellona; livello IV): 331 giocatori di futsal operati di LCA fra il 2020 e il 2024. Lesioni associate nel 57,1%: meniscali 51,4%, condrali 20,5%. Nelle revisioni (10,3%) le lesioni condrali sono il 55,9% contro il 16,2% (OR aggiustato 6,36; IC 95% 2,94-13,74), ma con soglia Outerbridge ≥ 2 l\'associazione non è più significativa (OR 2,13; IC 95% 0,87-5,23).',ax:'Barastegui, Ferre-Aniorte, Velasco, Vázquez, Ayestaran, Alvarez-Diaz, García-Bordes, Cugat',date:'nov 2026',meta:'serie retrospettiva consecutiva, 331 giocatori di futsal, livello IV, solo abstract',pmid:'42993978',doi:'10.1002/ksa.70675',journal:'Knee surgery, sports traumatology, arthroscopy',authors:'Barastegui D, Ferre-Aniorte A, Velasco P, Vázquez M, Ayestaran I, Alvarez-Diaz P, García-Bordes L, Cugat R',design:'Analisi retrospettiva di 331 giocatori di futsal consecutivi operati di ricostruzione del LCA in un centro specializzato (2020-2024). Rapporti operatori riesaminati nei casi ambigui; esclusi lesioni meniscali guarite, esiti di meniscectomia e menischi ipermobili senza rottura strutturale. Regressioni logistiche multivariate per i predittori delle lesioni associate. Livello IV. Covariate incluse, definizione di revisione e intervallo dalla prima ricostruzione: non riportati nell\'abstract.',pop:'331 giocatori di futsal (età media 23,0 ± 5,8 anni; 67,7% maschi), intervallo infortunio-intervento 4,0 ± 3,6 mesi. Revisioni 10,3%, cioè circa 34 casi (calcolo mio da 331).',results:'Lesioni associate nel 57,1% dei casi: meniscali 51,4%, condrali 20,5%. Fra i 68 con lesione condrale, Outerbridge 1 il 36,8%, 2 il 42,6%, 3 il 13,2%, 4 il 7,4%. Nelle revisioni le lesioni condrali sono più frequenti (55,9% contro 16,2%; p < 0,001): OR aggiustato 6,36 (IC 95% 2,94-13,74) per le lesioni condrali e 5,09 (IC 95% 2,25-11,49) per quelle meniscali e condrali combinate. Con soglia Outerbridge ≥ 2 l\'OR scende a 2,13 (IC 95% 0,87-5,23; p = 0,097). Sesso e superficie di gioco non sono predittori indipendenti.',concl:'Gli autori: i giocatori di futsal operati di LCA hanno un\'alta prevalenza di lesioni meniscali e condrali associate, e la revisione si lega a probabilità molto più alte di anomalie condrali, per lo più di grado basso; il significato clinico va confermato con studi longitudinali, ma la presenza di queste lesioni merita considerazione nella pianificazione e nella consulenza.',limits:'Serie retrospettiva di un solo centro, livello IV: associazione, non causa · Circa 34 revisioni, quindi l\'IC dell\'OR è molto largo (2,94-13,74) · Con soglia Outerbridge ≥ 2 l\'associazione non è più significativa (IC 95% 0,87-5,23): la forza del dato dipende dalle lesioni di grado 1 · Disegno trasversale: non dice se la lesione condrale preceda o segua la rottura dell\'innesto · Un solo sport e un solo centro · Covariate e intervallo dal primo intervento non riportati',perte:'Verde: tocca la cartilagine, un tuo filone (AMIC, minced cartilage), ma in un campione di futsal e con lesioni quasi sempre di grado 1-2. Cosa fare: nessun cambio di indicazione; nelle revisioni di LCA aspettati più spesso un danno condrale e prevedi la valutazione e la stadiazione in artroscopia. Lo studio non dice come trattare le lesioni di grado basso né se cambino l\'esito: non spinge verso AMIC o minced cartilage.'},
{n:4,mono:'m-gray',dot:'green',sec:'res',j:'JEO',h:'Instabilità rotulea: dopo MPFL e trocleoplastica la rotazione tibio-femorale cala di poco e segue l\'allineamento dell\'apparato estensore',v:'Serie retrospettiva (Mannheim e Pforzheim; livello IV): 141 pazienti operati per instabilità rotulea con ricostruzione del MPFL e trocleoplastica a lembo sottile, con osteotomia della tuberosità tibiale quando indicata. Tutti i parametri di allineamento migliorano (p < 0,001); la rotazione tibio-femorale cala di 1,55° (IC 95% 0,86-2,23) e il PT-TGA è l\'unico predittore indipendente della rotazione preoperatoria e della sua variazione.',ax:'Schmidt, Oudeh, Liodakis, Zimmermann, Balcarek',date:'nov 2026',meta:'serie retrospettiva, 141 pazienti, livello IV, solo abstract',pmid:'42991832',doi:'10.1002/jeo2.70979',journal:'Journal of experimental orthopaedics',authors:'Schmidt S, Oudeh AEN, Liodakis E, Zimmermann F, Balcarek P',design:'Analisi di 141 pazienti con instabilità rotulea ricorrente trattati con ricostruzione del MPFL e trocleoplastica a lembo sottile, con osteotomia della tuberosità tibiale (TTO) quando indicata. Parametri pre e postoperatori (bump trocleare, PT-TGA, sTTTG, TT-TG, inclinazione trocleare laterale, bisect offset, indice di Caton-Deschamps) insieme alla rotazione tibio-femorale (TFR). Correlazioni di Pearson o Spearman e regressioni lineari multivariate; affidabilità intra e interosservatore con ICC. Livello IV. Metodica di imaging e momento della misura postoperatoria: non riportati nell\'abstract.',pop:'141 pazienti (99 donne; età media 24,5 ± 8,2 anni) con instabilità rotulea ricorrente.',results:'Dopo l\'intervento migliorano tutti i parametri di allineamento (p < 0,001): bump trocleare −3,74 mm, PT-TGA −10,02°, sTTTG −4,57 mm. La TFR cala di 1,55° (IC 95% 0,86-2,23; p < 0,001). Prima dell\'intervento la TFR è legata soprattutto al PT-TGA (coefficiente 0,52) e al bisect offset (0,445); in regressione il PT-TGA è l\'unico predittore indipendente della TFR preoperatoria (0,33) e della sua variazione (0,376). ICC intraosservatore 0,947-0,992, interosservatore 0,877-0,956. Esiti clinici (punteggi, nuove lussazioni): non riportati nell\'abstract.',concl:'Gli autori: la TFR è legata all\'allineamento assiale femoro-rotuleo, soprattutto al PT-TGA, e cala dopo la stabilizzazione anche se la rotazione non viene corretta direttamente; va interpretata insieme all\'allineamento dell\'apparato estensore e non come parametro isolato e fisso.',limits:'Livello IV, retrospettivo: associazioni, non cause · Nessun esito clinico nell\'abstract (punteggi, ricadute, soddisfazione) · La variazione di 1,55° è piccola e l\'abstract non indica una soglia di rilevanza clinica · Un solo gruppo trattato, senza confronto: non separa l\'effetto di MPFL, trocleoplastica e osteotomia · Il tipo di coefficiente di correlazione non compare nell\'abstract · Solo abstract (PMC ID presente, testo non letto)',perte:'Verde: il MPFL è uno dei tuoi temi in evidenza. Il lavoro non porta esiti ma suggerisce che, in un ginocchio che ruota in modo anomalo, una parte della rotazione sia un riflesso dell\'allineamento rotuleo e si riduca quando lo si corregge. Cosa fare: nessun cambio; nella valutazione preoperatoria dell\'instabilità rotulea non attribuire alla sola tibia o al femore una rotazione che può dipendere dall\'apparato estensore, e leggi la TFR insieme al PT-TGA. Il dato non indica quando aggiungere trocleoplastica o osteotomia.'},
{n:5,mono:'m-gray',dot:'gray',sec:'res',j:'J Robot Surg',h:'Protesi robotica: la precisione di posizionamento è documentata, il beneficio clinico no; una revisione parla di «distanza fra precisione e bersaglio»',v:'Revisione narrativa di esperti (ricerche su PubMed, Embase e Web of Science del 28 aprile 2026; nessun conteggio di studi nell\'abstract). L\'evidenza più coerente è la riduzione degli errori di allineamento e di posizionamento dei componenti; i benefici funzionali e perioperatori variano per procedura, piattaforma, esito e follow-up. Tre autori sono affiliati a un\'azienda di sistemi robotici.',ax:'Xu, Fan, Kong, Jin, Li Z, Li D, He, Mamuladze, Korytkin, Li H, Zhai Z',date:'nov 2026',meta:'revisione narrativa di esperti, solo abstract',pmid:'42988998',doi:'10.1007/s11701-026-04149-z',journal:'Journal of robotic surgery',authors:'Xu Z, Fan W, Kong K, Jin M, Li Z, Li D, He C, Mamuladze T, Korytkin AA, Li H, Zhai Z',design:'Revisione narrativa di esperti con ricerche su PubMed, Embase e Web of Science del 28 aprile 2026. Priorità a revisioni sistematiche e trial randomizzati, integrati da studi osservazionali, di registro, economici e tecnici; valutazione qualitativa per disegno, follow-up, bias e differenze fra piattaforme, con esiti tecnici separati da quelli importanti per il paziente. Livello basso. Numero di studi inclusi e piattaforme considerate: non riportati nell\'abstract. Tre autori risultano affiliati a MicroPort NaviBot e Shanghai MicroPort MedBot; la dichiarazione di conflitto di interesse non è nell\'abstract.',pop:'Non applicabile (revisione narrativa); protesi di ginocchio e di anca.',results:'Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: la robotica riduce gli errori di posizionamento, ma il beneficio clinico generalizzabile a lungo termine è incoerente. Propongono la «distanza fra precisione e bersaglio»: un\'esecuzione più accurata dà poco se il bersaglio chirurgico non è validato per il paziente. Servono prove che il bersaglio migliori l\'esito e che la consegna robotica aggiunga beneficio; modelli paziente-specifici, sensori intraoperatori e supporto alle decisioni vanno validati con confronti prospettici con la tecnica convenzionale ottimizzata.',limits:'Revisione narrativa: la selezione degli studi non è riproducibile dall\'abstract e non c\'è alcun dato aggregato · Tre autori affiliati a un produttore di sistemi robotici: conflitto di interesse non dichiarato nell\'abstract · L\'abstract non distingue le piattaforme: non è detto che valga per il VELYS · Include anche l\'anca · Spiegazioni alternative (differenze piccole, confondimento, misura degli esiti) restano aperte secondo gli stessi autori',perte:'Grigio: nessuna decisione cambia. Per la tua pratica con il VELYS la lezione è di comunicazione: la precisione del robot è un dato tecnico documentato, il vantaggio clinico non lo è in modo generalizzabile. Cosa fare: nessun cambio; quando spieghi la protesi robotica a un paziente, descrivi l\'accuratezza dei tagli come dato tecnico e non come beneficio clinico provato (è anche ciò che chiede la normativa sulla comunicazione sanitaria).'}];

var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];

var BRIEF_TEXT="Domenica otto novembre, cinque lavori, nessuna scheda rossa. Apro con la settimana, che ha quattro lavori da ricordare. Il sette novembre un consensus di ventidue esperti ha indicato di considerare la centralizzazione del menisco, con la riparazione della radice e con il trapianto, quando l'estrusione alla risonanza supera tre millimetri: è opinione di livello cinque, muove la tensione sulla radice meniscale ma non cambia l'indicazione. Il quattro novembre una coorte pediatrica di UCLA su quattrocentododici ricostruzioni ha trovato più movimento limitato a tre mesi con la tenodesi laterale, sedici virgola otto per cento contro dieci virgola due, con un odds ratio aggiustato di due e un intervallo da uno virgola zero uno a tre virgola nove cinque: è il primo costo precoce del LET con quadricipite, e con un costrutto profondo, non il tuo. Il primo novembre, a cinque anni, le staminali da sangue cordonale con ialuronato hanno avuto punteggi migliori della microfrattura in una sottoanalisi di quarantotto pazienti, con tutti i limiti di una sottoanalisi. Il sei novembre una coorte di calciatori professionisti ha legato la rotazione tibio-femorale alla pendenza tibiale, ma è una misura di imaging senza esiti. Il cinque novembre non c'è stato briefing perché la ricerca su PubMed non rispondeva. Ora oggi. Nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi e nessun citante nuovo sui tuoi verdetti passati; il raccoglitore è quello di ieri mattina e tutte le fonti hanno risposto. Il lavoro del giorno viene da un registro di Stoccolma, su tremilaquattrocentocinquantotto operati di crociato con ischiocrurali: un rapporto più alto fra la forza degli ischiocrurali e quella del quadricipite a sei mesi si associa a meno revisioni entro due anni, odds ratio zero virgola otto uno, intervallo da zero virgola sette uno a zero virgola nove tre. Ma l'area sotto la curva è zero virgola sei quattro, quindi il test discrimina male, e l'innesto è quello di ischiocrurali, non il tuo. Muove soltanto di lato la tensione sul criterio di rientro. Seconda scheda, un'analisi economica della Mayo Clinic: quadricipite e rotuleo hanno il maggior valore, ma il quadricipite è preferito solo nel cinquantacinque virgola sette per cento delle simulazioni, quindi la differenza è instabile, e sono costi in dollari. Terza, calciatori di futsal operati di crociato: nelle revisioni le lesioni condrali sono più frequenti, odds ratio sei virgola tre sei, ma con la soglia di grado due l'associazione non è più significativa. Quarta, instabilità rotulea: su centoquarantun pazienti operati di MPFL e trocleoplastica la rotazione tibio-femorale cala di uno virgola cinque cinque gradi e segue l'allineamento dell'apparato estensore, senza esiti clinici. Quinta, una revisione narrativa sulla protesi robotica: la precisione è documentata, il beneficio clinico no, e tre autori sono affiliati a un'azienda di robot. Per il tuo VELYS vale come regola di comunicazione.";

